{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C144","C145","C129","C97","C147","C149","C187","C190","C156","C164","C176","C183","C188","C167"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C144","C145","C129","C147","C149","C187","C190","C167","C188"],
  "claims": [
    {
      "claim": "L4 records for the 4-hydroxycoumarin warfarin report a human fraction absorbed of 98%, supporting high intestinal absorption for the coumarin scaffold.",
      "card_ids": ["C144","C145","C129"]
    },
    {
      "claim": "L5 Caco-2 records for warfarin show high absorptive permeability (Papp A→B approximately 28-30 × 10^-6 cm/s) with efflux ratios of 0.4-1.0, indicating no P-gp-mediated gut-wall efflux.",
      "card_ids": ["C147","C149","C187","C190"]
    },
    {
      "claim": "L4/L5 records for coumarin derivatives decursin, decursinol, and anomalin show high Caco-2 permeability or well-absorbed classification with efflux ratios near 1.0-1.1, and decursin/decursinol angelate were reported as almost completely absorbed after oral dosing.",
      "card_ids": ["C97","C156","C164","C176","C183","C188","C167"]
    },
    {
      "claim": "L6 hepatic metabolism records are mostly for warfarin, naphthalene, flavonoids, and substituted coumarin probes; they show CYP-mediated metabolism but no direct coumarin extraction ratio or F. The warfarin L4/L5 records show high absorption and no efflux, so the L6 metabolism observations do not by themselves establish F < 20% for coumarin.",
      "card_ids": ["C213","C217","C239","C231","C243","C201","C144","C145","C129","C147","C149","C187","C190"]
    },
    {
      "claim": "The closest L6 metabolism records involve different scaffolds or substituents and do not report a coumarin extraction ratio or F; therefore they are not affirmative threshold-relevant low-F evidence.",
      "card_ids": ["C201","C231","C243"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C201","C213","C217","C228","C231","C239","C243","C246"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for coumarin itself is present in the supplied records.",
    "L6 hepatic clearance records do not include unsubstituted coumarin; the closest records are warfarin, BFC, and xanthotoxol, with no extraction-ratio or F values for coumarin.",
    "Potential first-pass metabolism of coumarin, such as 7-hydroxylation or lactone hydrolysis, is not directly evidenced in the supplied records and could lower parent F.",
    "Transfer from substituted coumarins such as warfarin, decursin, and BFC to unsubstituted coumarin is qualitative."
  ],
  "decision_summary": "Coumarin is predicted high for F >= 20%. The physicochemical prior is favorable, L4/L5 provide coumarin-scaffold absorption and permeability evidence with no gut-wall efflux, and L6 hepatic metabolism records are indirect and do not affirmatively establish F < 20% for coumarin. Confidence remains moderate because direct systemic F for coumarin is unmeasured and first-pass metabolism is unquantified."
}

